CREATE TABLE IF NOT EXISTS accounts (account_id BIGSERIAL PRIMARY KEY, username VARCHAR(32) UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS characters (character_id BIGSERIAL PRIMARY KEY, account_id BIGINT NOT NULL REFERENCES accounts(account_id), name VARCHAR(32) UNIQUE NOT NULL, level INTEGER NOT NULL DEFAULT 1, room_id INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS inventory (character_id BIGINT NOT NULL REFERENCES characters(character_id), item_id BIGINT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(character_id,item_id));
